<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;rawSettings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
